import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import "./AdminDashboard.css";

const AdminDashboard = () => {
  const navigate = useNavigate();
  const [users, setUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [votingResults, setVotingResults] = useState(null);
  const [loading, setLoading] = useState(true);
  const [exportLoading, setExportLoading] = useState(false);
  const [activeTab, setActiveTab] = useState("users");
  const [newCandidate, setNewCandidate] = useState({ name: "", party: "" });
  const [blockchainStatus, setBlockchainStatus] = useState(null);

  // Get admin token
  const getAuthToken = () => {
    return localStorage.getItem("adminToken") || "admin-auth-token";
  };

  useEffect(() => {
    // Check if admin is authenticated
    const token = getAuthToken();
    if (!token) {
      navigate("/admin-login");
      return;
    }
    fetchUsers();
    fetchCandidates();
    checkBlockchainStatus();
  }, [navigate]);

  const fetchUsers = async () => {
    try {
      const token = getAuthToken();
      const response = await axios.get("http://localhost:5000/api/users", {
        headers: { Authorization: token },
      });
      setUsers(response.data);
      setLoading(false);
    } catch (error) {
      console.error("Error fetching users:", error);
      if (error.response?.status === 401) {
        localStorage.removeItem("adminToken");
        navigate("/admin-login");
      }
      setLoading(false);
    }
  };

  const fetchCandidates = async () => {
    try {
      console.log("🔄 Fetching candidates...");
      const response = await axios.get("http://localhost:5000/api/candidates");
      console.log("✅ Candidates fetched:", response.data);
      setCandidates(response.data);
    } catch (error) {
      console.error("❌ Error fetching candidates:", error);
      alert(
        "Failed to fetch candidates: " +
          (error.response?.data?.message || error.message)
      );
    }
  };

  const fetchVotingResults = async () => {
    try {
      const token = getAuthToken();
      const response = await axios.get(
        "http://localhost:5000/api/voting-results",
        {
          headers: { Authorization: token },
        }
      );
      setVotingResults(response.data);
    } catch (error) {
      console.error("Error fetching voting results:", error);
    }
  };

  const checkBlockchainStatus = async () => {
    try {
      const response = await axios.get(
        "http://localhost:5000/api/blockchain/status"
      );
      setBlockchainStatus(response.data.blockchain);
    } catch (error) {
      console.error("Error checking blockchain status:", error);
    }
  };

  const exportToExcel = async () => {
    try {
      setExportLoading(true);
      const token = getAuthToken();
      const response = await axios.get(
        "http://localhost:5000/api/export-excel",
        {
          headers: { Authorization: token },
          responseType: "blob",
        }
      );

      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement("a");
      link.href = url;
      link.setAttribute(
        "download",
        `UserVerifications_${new Date().getTime()}.xlsx`
      );
      document.body.appendChild(link);
      link.click();
      link.remove();

      alert("✅ Excel file downloaded successfully!");
    } catch (error) {
      console.error("Error exporting Excel:", error);
      alert(
        "❌ Error exporting Excel file: " +
          (error.response?.data?.message || error.message)
      );
    } finally {
      setExportLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem("adminToken");
    navigate("/admin-login");
  };

  const goToUserLogin = () => {
    navigate("/login");
  };

  const addCandidate = async () => {
    if (!newCandidate.name || !newCandidate.party) {
      alert("Please enter candidate name and party");
      return;
    }

    try {
      const token = getAuthToken();
      console.log("🔄 Adding candidate:", newCandidate);
      console.log("🔑 Using token:", token);

      const response = await axios.post(
        "http://localhost:5000/api/candidates",
        {
          name: newCandidate.name.trim(),
          party: newCandidate.party.trim(),
        },
        {
          headers: {
            Authorization: token,
            "Content-Type": "application/json",
          },
        }
      );

      console.log("✅ Candidate response:", response.data);

      if (response.data.success) {
        alert("✅ Candidate added successfully!");
        setNewCandidate({ name: "", party: "" });
        fetchCandidates(); // Refresh the list
      }
    } catch (error) {
      console.error("❌ Error adding candidate:", error);

      if (error.response) {
        console.error("Response status:", error.response.status);
        console.error("Response data:", error.response.data);
        console.error("Response headers:", error.response.headers);

        alert(
          `❌ Failed to add candidate: ${
            error.response.data.message ||
            error.response.statusText ||
            "Unknown error"
          }`
        );
      } else if (error.request) {
        console.error("No response received:", error.request);
        alert(
          "❌ No response from server. Check if backend is running on port 5000."
        );
      } else {
        console.error("Error message:", error.message);
        alert("❌ Error: " + error.message);
      }
    }
  };

  const deleteCandidate = async (candidateId) => {
    if (!window.confirm("Are you sure you want to delete this candidate?")) {
      return;
    }

    try {
      const token = getAuthToken();
      const response = await axios.delete(
        `http://localhost:5000/api/candidates/${candidateId}`,
        {
          headers: { Authorization: token },
        }
      );

      if (response.data.success) {
        alert("✅ Candidate deleted successfully!");
        fetchCandidates();
      }
    } catch (error) {
      console.error("Error deleting candidate:", error);
      alert(
        "❌ Failed to delete candidate: " +
          (error.response?.data?.message || error.message)
      );
    }
  };

  const viewFaceImage = (faceImage) => {
    if (faceImage) {
      const imageUrl = `http://localhost:5000/uploads/${faceImage}`;
      window.open(imageUrl, "_blank");
    }
  };

  if (loading) return <div className="loading">Loading user data...</div>;

  return (
    <div className="admin-dashboard">
      <div className="dashboard-header">
        <div>
          <h1>👨‍💼 E-Voting Admin Dashboard</h1>
          <p>Manage and monitor user verifications and voting</p>
        </div>
        <div className="header-actions">
          <button onClick={goToUserLogin} className="user-login-btn">
            👤 User Login
          </button>
          <button onClick={handleLogout} className="logout-btn">
            🚪 Logout
          </button>
        </div>
      </div>

      {/* Blockchain Status Component */}
      {blockchainStatus && (
        <div
          className="blockchain-status"
          style={{
            background: blockchainStatus.connected
              ? "rgba(39, 174, 96, 0.2)"
              : "rgba(231, 76, 60, 0.2)",
            border: `1px solid ${
              blockchainStatus.connected
                ? "rgba(39, 174, 96, 0.5)"
                : "rgba(231, 76, 60, 0.5)"
            }`,
            padding: "15px",
            borderRadius: "8px",
            marginBottom: "20px",
            color: "white",
          }}
        >
          <h3>
            🔗 Blockchain Status:{" "}
            {blockchainStatus.connected ? "✅ Connected" : "❌ Disconnected"}
          </h3>
          {blockchainStatus.connected ? (
            <div style={{ fontSize: "14px", marginTop: "8px" }}>
              <div>
                <strong>Contract:</strong>{" "}
                {blockchainStatus.contractLoaded
                  ? "✅ Loaded"
                  : "❌ Not Loaded"}
              </div>
              <div>
                <strong>Network ID:</strong> {blockchainStatus.networkId}
              </div>
              <div>
                <strong>Admin Address:</strong>{" "}
                {blockchainStatus.adminAddress
                  ? blockchainStatus.adminAddress.substring(0, 20) + "..."
                  : "N/A"}
              </div>
            </div>
          ) : (
            <div style={{ fontSize: "14px", marginTop: "8px" }}>
              <p>💡 Make sure Ganache is running on http://localhost:7545</p>
              <p>
                Running in database-only mode. Votes will be stored in database.
              </p>
            </div>
          )}
        </div>
      )}

      <div className="dashboard-stats">
        <div className="stat-card total-users">
          <h3>Total Verified Users</h3>
          <p>{users.length}</p>
        </div>
        <div className="stat-card today-users">
          <h3>Today's Verifications</h3>
          <p>
            {
              users.filter((user) => {
                const today = new Date().toDateString();
                const userDate = new Date(user.timestamp).toDateString();
                return today === userDate;
              }).length
            }
          </p>
        </div>
        <div className="stat-card unique-voters">
          <h3>Total Votes Cast</h3>
          <p>{users.filter((user) => user.has_voted).length}</p>
        </div>
        <div className="stat-card candidates-count">
          <h3>Candidates</h3>
          <p>{candidates.length}</p>
        </div>
      </div>

      <div className="dashboard-tabs">
        <button
          className={`tab-btn ${activeTab === "users" ? "active" : ""}`}
          onClick={() => setActiveTab("users")}
        >
          👥 Users
        </button>
        <button
          className={`tab-btn ${activeTab === "candidates" ? "active" : ""}`}
          onClick={() => setActiveTab("candidates")}
        >
          🗳️ Candidates
        </button>
        <button
          className={`tab-btn ${activeTab === "results" ? "active" : ""}`}
          onClick={() => {
            setActiveTab("results");
            fetchVotingResults();
          }}
        >
          📊 Results
        </button>
      </div>

      <div className="dashboard-actions">
        {activeTab === "users" && (
          <button
            onClick={exportToExcel}
            className="export-btn"
            disabled={users.length === 0 || exportLoading}
          >
            {exportLoading
              ? "📊 Exporting..."
              : `📊 Export to Excel (${users.length} records)`}
          </button>
        )}
        <button onClick={fetchUsers} className="refresh-btn">
          🔄 Refresh Data
        </button>
        <button onClick={checkBlockchainStatus} className="refresh-btn">
          🔗 Check Blockchain
        </button>
      </div>

      {activeTab === "users" &&
        (users.length === 0 ? (
          <div className="no-data">
            <h3>📭 No user verification data found</h3>
            <p>
              Users will appear here after they complete verification through
              the user login page.
            </p>
          </div>
        ) : (
          <div className="users-table-container">
            <table className="users-table">
              <thead>
                <tr>
                  <th>ID</th>
                  <th>Name</th>
                  <th>Aadhar Number</th>
                  <th>Phone Number</th>
                  <th>OTP</th>
                  <th>Face Image</th>
                  <th>Voter ID</th>
                  <th>Email</th>
                  <th>Email OTP</th>
                  <th>Has Voted</th>
                  <th>Blockchain Address</th>
                  <th>IP Address</th>
                  <th>Timestamp</th>
                </tr>
              </thead>
              <tbody>
                {users.map((user) => (
                  <tr key={user.ID || user.id}>
                    <td>{user.ID || user.id}</td>
                    <td>{user.name}</td>
                    <td>{user.aadhar_number || user.aadhaar_number}</td>
                    <td>{user.phone_number}</td>
                    <td>{user.otp}</td>
                    <td>
                      {user.face_image ? (
                        <button
                          className="view-image-btn"
                          onClick={() => viewFaceImage(user.face_image)}
                          title="Click to view face image"
                        >
                          📷 View
                        </button>
                      ) : (
                        "❌"
                      )}
                    </td>
                    <td>{user.voterid || user.voter_id}</td>
                    <td>{user.email}</td>
                    <td>{user.email_otp}</td>
                    <td>{user.has_voted ? "✅ Yes" : "❌ No"}</td>
                    <td title={user.blockchain_address}>
                      {user.blockchain_address
                        ? user.blockchain_address.substring(0, 10) + "..."
                        : "❌ No"}
                    </td>
                    <td>{user.ip_address}</td>
                    <td>{new Date(user.timestamp).toLocaleString()}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ))}

      {activeTab === "candidates" && (
        <div className="candidates-management">
          <div className="add-candidate-form">
            <h3>Add New Candidate</h3>
            <div className="form-row">
              <input
                type="text"
                placeholder="Candidate Name"
                value={newCandidate.name}
                onChange={(e) =>
                  setNewCandidate({ ...newCandidate, name: e.target.value })
                }
                className="form-input"
              />
              <input
                type="text"
                placeholder="Party"
                value={newCandidate.party}
                onChange={(e) =>
                  setNewCandidate({ ...newCandidate, party: e.target.value })
                }
                className="form-input"
              />
              <button onClick={addCandidate} className="add-btn">
                ➕ Add Candidate
              </button>
            </div>
          </div>

          <div className="candidates-list">
            <h3>Candidates List {blockchainStatus?.connected && "🔗"}</h3>
            {candidates.length === 0 ? (
              <div className="no-data">
                <p>No candidates added yet.</p>
              </div>
            ) : (
              <div className="candidates-grid">
                {candidates.map((candidate) => (
                  <div key={candidate.id} className="candidate-item">
                    <div className="candidate-details">
                      <h4>
                        {candidate.name} {candidate.blockchain_enabled && "🔗"}
                      </h4>
                      <p>Party: {candidate.party}</p>
                      <p>Database Votes: {candidate.votes}</p>
                      {candidate.blockchain_enabled && (
                        <p>Total Votes: {candidate.total_votes}</p>
                      )}
                    </div>
                    <button
                      onClick={() => deleteCandidate(candidate.id)}
                      className="delete-btn"
                    >
                      🗑️ Delete
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      )}

      {activeTab === "results" && (
        <div className="voting-results">
          <h3>
            📊 Voting Results {votingResults?.blockchain?.enabled && "🔗"}
          </h3>
          {votingResults ? (
            <div className="results-container">
              <div className="results-summary">
                <h4>Total Votes Cast: {votingResults.totalVotes}</h4>
                {votingResults.blockchain && (
                  <p
                    style={{
                      color: votingResults.blockchain.enabled
                        ? "#28a745"
                        : "#dc3545",
                      marginTop: "10px",
                    }}
                  >
                    <strong>Blockchain:</strong>{" "}
                    {votingResults.blockchain.enabled
                      ? "✅ Integrated"
                      : "❌ Database Only"}
                  </p>
                )}
              </div>
              <div className="results-list">
                {votingResults.candidates.map((candidate, index) => (
                  <div
                    key={candidate.id}
                    className={`result-item ${index === 0 ? "winner" : ""}`}
                  >
                    <div className="candidate-rank">
                      #{index + 1}
                      {index === 0 && " 🏆"}
                    </div>
                    <div className="candidate-info">
                      <h4>
                        {candidate.name} {candidate.blockchain_enabled && "🔗"}
                      </h4>
                      <p>{candidate.party}</p>
                      {candidate.blockchain_enabled && (
                        <p style={{ fontSize: "12px", color: "#666" }}>
                          Database: {candidate.votes} votes | Total:{" "}
                          {candidate.total_votes} votes
                        </p>
                      )}
                    </div>
                    <div className="vote-count">
                      <strong>
                        {candidate.total_votes || candidate.votes} votes
                      </strong>
                      {votingResults.totalVotes > 0 && (
                        <span className="vote-percentage">
                          (
                          {Math.round(
                            ((candidate.total_votes || candidate.votes) /
                              votingResults.totalVotes) *
                              100
                          )}
                          %)
                        </span>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ) : (
            <div className="no-data">
              <p>Click "Refresh Data" to load voting results</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;
